/** Set by vite.config.ts at build time. */
declare const __CASAMA_TARGET__: "dev" | "store";
declare const __CASAMA_VERSION__: string;
/** "firefox" for Firefox, "safari" for Safari, "chromium" for Chrome, Edge, Opera and the rest. */
declare const __CASAMA_BROWSER__: "chromium" | "firefox" | "safari";
/** Official-build crash reporting config (empty in dev, e2e and self-hosted builds; D-539). */
declare const __CASAMA_SENTRY_DSN__: string;
declare const __CASAMA_POSTHOG_KEY__: string;
declare const __CASAMA_POSTHOG_HOST__: string;
